<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Sorting Visualizer</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            background: linear-gradient(135deg, #0f0f0f 0%, #1a1a1a 100%);
            color: #fff;
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            padding: 20px;
        }

        .container {
            width: 100%;
            max-width: 1000px;
        }

        h1 {
            text-align: center;
            margin-bottom: 40px;
            font-size: 2.5rem;
            font-weight: 300;
            letter-spacing: 2px;
        }

        .controls {
            display: flex;
            gap: 12px;
            margin-bottom: 40px;
            justify-content: center;
            flex-wrap: wrap;
        }

        button {
            padding: 12px 28px;
            font-size: 1rem;
            font-weight: 500;
            background-color: #0066cc;
            color: white;
            border: none;
            border-radius: 8px;
            cursor: pointer;
            transition: all 0.3s ease;
            box-shadow: 0 4px 15px rgba(0, 102, 204, 0.3);
        }

        button:hover {
            background-color: #0052a3;
            transform: translateY(-2px);
            box-shadow: 0 6px 20px rgba(0, 102, 204, 0.4);
        }

        button:active {
            transform: translateY(0);
        }

        #bars {
            display: flex;
            align-items: flex-end;
            justify-content: space-around;
            height: 450px;
            background: linear-gradient(180deg, #1a1a1a 0%, #222 100%);
            border-radius: 12px;
            padding: 25px 15px;
            gap: 3px;
            border: 2px solid #333;
        }

        .bar {
            flex: 1;
            background: linear-gradient(180deg, #4a9eff 0%, #0066cc 100%);
            border-radius: 6px 6px 0 0;
            transition: height 0.1s ease-out, background 0.15s ease;
            min-width: 0;
            box-shadow: 0 4px 12px rgba(74, 158, 255, 0.4);
            position: relative;
        }

        .bar.comparing {
            background: linear-gradient(180deg, #ffb347 0%, #ff8c00 100%);
            box-shadow: 0 4px 16px rgba(255, 140, 0, 0.6);
        }

        .bar.sorted {
            background: linear-gradient(180deg, #4ade80 0%, #22c55e 100%);
            box-shadow: 0 4px 12px rgba(74, 222, 128, 0.5);
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>Sorting Visualizer</h1>
        <div class="controls">
            <button id="sort">Sort</button>
            <button id="shuffle">Shuffle</button>
            <button id="reset">Reset</button>
        </div>
        <div id="bars"></div>
    </div>

    <script>
        class SortVisualizer {
            constructor() {
                this.arr = [];
                this.i = 0;
                this.j = 0;
                this.comparingIndices = [];
                this.sortedIndices = new Set();
                this.isSorting = false;
                this.isComplete = false;
                this.init();
                this.attachEventListeners();
            }

            init() {
                this.arr = Array.from({ length: 20 }, (_, idx) => idx + 1);
                this.shuffle();
            }

            shuffle() {
                for (let i = this.arr.length - 1; i > 0; i--) {
                    const j = Math.floor(Math.random() * (i + 1));
                    [this.arr[i], this.arr[j]] = [this.arr[j], this.arr[i]];
                }
                this.resetSort();
                this.render();
            }

            resetSort() {
                this.i = 0;
                this.j = 0;
                this.comparingIndices = [];
                this.sortedIndices.clear();
                this.isSorting = false;
                this.isComplete = false;
            }

            render() {
                const barsContainer = document.getElementById('bars');
                barsContainer.innerHTML = '';
                const maxVal = Math.max(...this.arr);

                this.arr.forEach((val, idx) => {
                    const bar = document.createElement('div');
                    bar.className = 'bar';

                    if (this.sortedIndices.has(idx)) {
                        bar.classList.add('sorted');
                    } else if (this.comparingIndices.includes(idx)) {
                        bar.classList.add('comparing');
                    }

                    bar.style.height = (val / maxVal * 100) + '%';
                    barsContainer.appendChild(bar);
                });
            }

            sortStep() {
                if (this.isComplete) {
                    return true;
                }

                const n = this.arr.length;

                if (!this.isSorting) {
                    this.isSorting = true;
                    this.i = 0;
                    this.j = 0;
                }

                if (this.i >= n - 1) {
                    this.isComplete = true;
                    this.comparingIndices = [];
                    this.sortedIndices.clear();
                    for (let k = 0; k < n; k++) {
                        this.sortedIndices.add(k);
                    }
                    this.render();
                    return true;
                }

                if (this.j >= n - 1 - this.i) {
                    this.i++;
                    this.j = 0;

                    for (let k = n - this.i; k < n; k++) {
                        this.sortedIndices.add(k);
                    }

                    if (this.i >= n - 1) {
                        this.isComplete = true;
                        this.comparingIndices = [];
                        for (let k = 0; k < n; k++) {
                            this.sortedIndices.add(k);
                        }
                        this.render();
                        return true;
                    }

                    this.render();
                    return false;
                }

                this.comparingIndices = [this.j, this.j + 1];

                if (this.arr[this.j] > this.arr[this.j + 1]) {
                    [this.arr[this.j], this.arr[this.j + 1]] = [this.arr[this.j + 1], this.arr[this.j]];
                }

                this.j++;
                this.render();
                return false;
            }

            sorted() {
                for (let i = 0; i < this.arr.length - 1; i++) {
                    if (this.arr[i] > this.arr[i + 1]) {
                        return false;
                    }
                }
                return true;
            }

            array() {
                return [...this.arr];
            }

            setArray(arr) {
                this.arr = [...arr];
                this.resetSort();
                this.render();
            }

            attachEventListeners() {
                document.getElementById('sort').addEventListener('click', () => {
                    this.resetSort();
                    const interval = setInterval(() => {
                        const done = this.sortStep();
                        if (done) clearInterval(interval);
                    }, 50);
                });

                document.getElementById('shuffle').addEventListener('click', () => {
                    this.shuffle();
                });

                document.getElementById('reset').addEventListener('click', () => {
                    this.init();
                });
            }
        }

        const visualizer = new SortVisualizer();

        window.viz = {
            array: () => visualizer.array(),
            setArray: (a) => visualizer.setArray(a),
            sortStep: () => visualizer.sortStep(),
            sorted: () => visualizer.sorted(),
        };
    </script>
</body>
</html>
